-- Create "timetable_deviations" table
CREATE TABLE "timetable_deviations" ("id" uuid NOT NULL, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now(), "deviation_date" date NOT NULL, "kind" character varying NOT NULL, "start_minute" bigint NULL, "end_minute" bigint NULL, "reason" text NULL, "period_id" uuid NOT NULL, "room_id" uuid NULL, "section_id" uuid NOT NULL, "subject_offering_id" uuid NULL, "substitute_teacher_id" uuid NULL, "created_by" uuid NULL, "timetable_slot_id" uuid NULL, PRIMARY KEY ("id"), CONSTRAINT "timetable_deviations_periods_deviations" FOREIGN KEY ("period_id") REFERENCES "periods" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "timetable_deviations_persons_creator" FOREIGN KEY ("created_by") REFERENCES "persons" ("id") ON UPDATE NO ACTION ON DELETE SET NULL, CONSTRAINT "timetable_deviations_rooms_deviations" FOREIGN KEY ("room_id") REFERENCES "rooms" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "timetable_deviations_sections_section" FOREIGN KEY ("section_id") REFERENCES "sections" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "timetable_deviations_subject_offerings_subject_offering" FOREIGN KEY ("subject_offering_id") REFERENCES "subject_offerings" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "timetable_deviations_teachers_substitute_teacher" FOREIGN KEY ("substitute_teacher_id") REFERENCES "teachers" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "timetable_deviations_timetable_slots_deviations" FOREIGN KEY ("timetable_slot_id") REFERENCES "timetable_slots" ("id") ON UPDATE NO ACTION ON DELETE CASCADE, CONSTRAINT "timetable_deviations_added_has_no_slot" CHECK ((((kind)::text = 'added'::text) AND (timetable_slot_id IS NULL) AND (subject_offering_id IS NOT NULL)) OR (((kind)::text <> 'added'::text) AND (timetable_slot_id IS NOT NULL))), CONSTRAINT "timetable_deviations_minute_range" CHECK (((start_minute IS NULL) AND (end_minute IS NULL)) OR ((start_minute >= 0) AND (end_minute > start_minute) AND (end_minute <= 1440))), CONSTRAINT "timetable_deviations_room_present" CHECK (((kind)::text <> 'room_change'::text) OR (room_id IS NOT NULL)), CONSTRAINT "timetable_deviations_substitute_present" CHECK (((kind)::text <> 'substitution'::text) OR (substitute_teacher_id IS NOT NULL)), CONSTRAINT "timetable_deviations_time_present" CHECK (((kind)::text <> 'time_change'::text) OR ((start_minute IS NOT NULL) AND (end_minute IS NOT NULL))));
-- Create index "timetabledeviation_deviation_date" to table: "timetable_deviations"
CREATE INDEX "timetabledeviation_deviation_date" ON "timetable_deviations" ("deviation_date");
-- Create index "timetabledeviation_room_id_deviation_date" to table: "timetable_deviations"
CREATE INDEX "timetabledeviation_room_id_deviation_date" ON "timetable_deviations" ("room_id", "deviation_date");
-- Create index "timetabledeviation_section_id__283ca34134bbe074a0a738d44a90704e" to table: "timetable_deviations"
CREATE UNIQUE INDEX "timetabledeviation_section_id__283ca34134bbe074a0a738d44a90704e" ON "timetable_deviations" ("section_id", "deviation_date", "period_id", "subject_offering_id") WHERE (timetable_slot_id IS NULL);
-- Create index "timetabledeviation_section_id_deviation_date" to table: "timetable_deviations"
CREATE INDEX "timetabledeviation_section_id_deviation_date" ON "timetable_deviations" ("section_id", "deviation_date");
-- Create index "timetabledeviation_substitute_teacher_id_deviation_date" to table: "timetable_deviations"
CREATE INDEX "timetabledeviation_substitute_teacher_id_deviation_date" ON "timetable_deviations" ("substitute_teacher_id", "deviation_date");
-- Create index "timetabledeviation_timetable_slot_id_deviation_date" to table: "timetable_deviations"
CREATE UNIQUE INDEX "timetabledeviation_timetable_slot_id_deviation_date" ON "timetable_deviations" ("timetable_slot_id", "deviation_date");
